function createWeapon(notify=true){if(rigWeapon!==null){magazineInventory.set(rigWeapon,ammo);reserveInventory.set(rigWeapon,reserveAmmo)}cancelDraw();if(weaponRig){viewScene.remove(weaponRig);weaponRig.traverse(o=>{o.geometry?.dispose();if(o.material?.transparent||o.isLine)o.material?.dispose()})}const w=weapons[selectedWeapon],pistol=w.cat==='hg',sniper=w.cat==='sr',sg=w.cat==='sg',smg=w.cat==='smg',lmg=w.cat==='lmg';weaponRig=new THREE.Group();weaponRig.scale.setScalar(.7);viewScene.add(weaponRig);const metal=0x29332e,body=w.color,accent=0xd3f878;if(w.mechanic){createSpecialWeapon(w);finishWeapon(w,notify);return}const length=(pistol?.47:sniper?1.18:sg?1.02:smg?.64:.88)*( .96+(w.id%4)*.025);box(weaponRig,0,0,0,pistol?.14:.19,pistol?.16:.22,length,body,{metal:.65,rough:.38});box(weaponRig,0,.12,-length*.1,.14,.055,length*.73,metal,{metal:.7});for(let i=0;i<9;i++)box(weaponRig,0,.16,-length*.4+i*length*.065,.16,.035,.025,metal,{metal:.7});box(weaponRig,0,-.18,length*.27,.13,.3,.16,metal,{metal:.5});const mag=box(weaponRig,0,-.26,pistol?length*.2:-length*.07,lmg?.3:.12,lmg?.24:.31,lmg?.26:.2,metal,{metal:.5});mag.rotation.x=pistol?0:-.15;if(!pistol){box(weaponRig,0,.005,length*.68,.16,.2,.45,metal,{metal:.4});box(weaponRig,0,-.025,length*.92,.2,.29,.07,body);box(weaponRig,0,0,-length*.39,.23,.2,length*.4,metal);for(let i=0;i<5;i++){box(weaponRig,-.119,.015,-length*.5+i*.07,.012,.1,.03,body);box(weaponRig,.119,.015,-length*.5+i*.07,.012,.1,.03,body)}}const barrel=cylinder(weaponRig,0,.02,-length*.72,.035,.035,length*.4,0x3b4740,12);barrel.rotation.x=Math.PI/2;const tip=-length*.92;const muzzlePart=cylinder(weaponRig,0,.02,tip,.05,.05,.09,metal);muzzlePart.rotation.x=Math.PI/2;box(weaponRig,.105,.015,.17,.011,.08,.12,accent);box(weaponRig,-.105,.025,.12,.011,.04,.1,0x7f8c73);const glove=0x303e32,sleeve=0x657456;const right=box(weaponRig,.07,-.25,.29,.18,.23,.24,glove);right.rotation.x=-.2;const forearm=box(weaponRig,.16,-.42,.49,.22,.23,.57,sleeve);forearm.rotation.x=-.25;forearm.visible=false;const left=box(weaponRig,-.13,-.16,-.3,.18,.2,.28,glove);left.rotation.z=-.15;const lf=box(weaponRig,-.3,-.32,-.02,.22,.22,.65,sleeve);lf.rotation.y=-.5;lf.visible=false;const bolt=box(weaponRig,.104,.045,.06,.018,.065,.16,0x778877,{metal:.8});weaponParts={mag,bolt,supportHand:left,triggerHand:right};muzzle=new THREE.Mesh(new THREE.ConeGeometry(.14,.35,7),new THREE.MeshBasicMaterial({color:0xffe2a0,transparent:true,opacity:.85}));muzzle.rotation.x=-Math.PI/2;muzzle.position.set(0,.02,tip-.18);muzzle.visible=false;weaponRig.add(muzzle);muzzleLight=new THREE.PointLight(0xffd98b,0,3);muzzleLight.position.set(0,.05,tip);weaponRig.add(muzzleLight);addWeaponDetails(THREE,weaponRig,w);finishWeapon(w,notify)}
function restTransform(node){return {p:node.position.toArray(),r:[node.rotation.x,node.rotation.y,node.rotation.z]}}
function applyModelPose(node,base,position=[0,0,0],rotation=[0,0,0]){if(!node||!base)return;node.position.set(base.p[0]+position[0],base.p[1]+position[1],base.p[2]+position[2]);node.rotation.set(base.r[0]+rotation[0],base.r[1]+rotation[1],base.r[2]+rotation[2])}
function finishWeapon(w,notify=true){addViewArms(THREE,weaponRig,weaponParts,mat(0x657456));weaponParts.rest={};for(const[key,part]of Object.entries(weaponParts))if(part?.isObject3D)weaponParts.rest[key]=restTransform(part);aim=false;rigWeapon=selectedWeapon;ammo=magazineInventory.get(selectedWeapon)??w.mag;reserveAmmo=reserveInventory.get(selectedWeapon)??w.reserve;reloading=0;pendingReload=0;weaponSwitch=.4;shotCooldown=Math.max(shotCooldown,.25);updateWeaponHud();renderQuickSlots();if(combat&&mode==='online'&&notify){pendingOnlineShots=[];pendingEquip=++actionSeq;net.send({type:'equip',weapon:selectedWeapon,seq:pendingEquip})}else pendingEquip=0}
function applyServerLoadout(packet,serverTime){
 if(packet.weapon!==selectedWeapon)return;
 const oldAmmo=ammo,oldReserve=reserveAmmo,wasReloading=reloading>0,w=weapons[selectedWeapon];
 ammo=w.mechanic==='melee'?1:Math.min(w.mag,Math.max(0,packet.ammo-pendingOnlineShots.length));
 if(Number.isFinite(packet.reserve))reserveAmmo=Math.max(0,Math.min(w.reserve,packet.reserve));
 reserveInventory.set(selectedWeapon,reserveAmmo);
 reloading=packet.health===0?0:Math.max(0,((packet.reloadAt||0)-serverTime)/1000);
 magazineInventory.set(selectedWeapon,ammo);
 if(wasReloading&&reloading===0&&ammo>oldAmmo&&!paused)sound('reload');
 if(oldAmmo!==ammo||oldReserve!==reserveAmmo||wasReloading!==(reloading>0)){updateWeaponHud();$('reloadHint').innerHTML=reloading>0?'재장전 중…':'R 재장전 <b>·</b> 1~3 무기 전환 <b>·</b> B 무기고'}
}
function syncInventoryFromSnapshot(self,serverTime){if(pendingEquip||pendingReload||self.weapon!==selectedWeapon)return;applyServerLoadout(self,serverTime)}
function handleEquipAck(m){
 if(!combat||mode!=='online'||!pendingEquip||m.seq!==pendingEquip)return;
 pendingEquip=0;
 if(Number.isInteger(m.weapon)&&weapons[m.weapon]&&m.weapon!==selectedWeapon){pendingReload=0;pendingOnlineShots=[];selectedWeapon=m.weapon;inspectedWeapon=m.weapon;storage.set('weapon',selectedWeapon);createWeapon(false)}
 if(!pendingReload)applyServerLoadout(m,m.serverTime??net.serverNow);
}
function handleReloadAck(m){
 if(!combat||mode!=='online'||!pendingReload||m.seq!==pendingReload)return;
 pendingReload=0;if(!pendingEquip&&m.weapon===selectedWeapon)applyServerLoadout(m,m.serverTime??net.serverNow);
}
function handleShotAck(m){
 if(!combat||mode!=='online'||m.weapon!==selectedWeapon)return;
 pendingOnlineShots=pendingOnlineShots.filter(n=>n>m.seq);
 if(!pendingEquip&&!pendingReload)applyServerLoadout(m,m.serverTime??net.serverNow);
}
function createSpecialWeapon(w){
 const metal=0x283b34,handle=0x83966c;weaponParts={mag:new THREE.Object3D()};
 if(w.crossbow){weaponParts=makeCrossbow(THREE,weaponRig,w);weaponParts.supportHand=weaponRig.getObjectByName('crossbow-support-hand');weaponParts.triggerHand=weaponRig.getObjectByName('crossbow-trigger-hand')}else if(w.mechanic==='arrow'){
  const curve=new THREE.CatmullRomCurve3([new THREE.Vector3(0,-.72,-.17),new THREE.Vector3(0,-.43,-.4),new THREE.Vector3(0,0,-.46),new THREE.Vector3(0,.43,-.4),new THREE.Vector3(0,.72,-.17)]);
  weaponRig.add(new THREE.Mesh(new THREE.TubeGeometry(curve,24,.035,8,false),mat(0x89a276,.5,.4)));box(weaponRig,0,0,-.44,.08,.26,.1,metal);const string=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0,.72,-.17),new THREE.Vector3(0,0,.12),new THREE.Vector3(0,-.72,-.17)]),new THREE.LineBasicMaterial({color:0xe7f4c4}));weaponRig.add(string);weaponParts.string=string;
  const arrow=new THREE.Group(),shaft=cylinder(arrow,0,0,-.3,.009,.009,1.1,0xb3bea0,6);shaft.rotation.x=Math.PI/2;const tip=new THREE.Mesh(new THREE.ConeGeometry(.035,.12,4),mat(0xd3f878,.6,.3));tip.rotation.x=-Math.PI/2;tip.position.z=-.91;arrow.add(tip);weaponRig.add(arrow);weaponParts.arrow=arrow;weaponParts.supportHand=box(weaponRig,-.04,-.12,-.36,.15,.19,.2,metal);const hand=box(weaponRig,.035,-.02,.14,.16,.16,.18,metal);weaponParts.drawHand=hand;weaponParts.triggerHand=hand;
 }else if(w.mechanic==='rocket'){
  const tube=cylinder(weaponRig,0,0,0,.14,.14,1.45,handle,14);tube.rotation.x=Math.PI/2;for(const z of [-.7,.65]){const rim=cylinder(weaponRig,0,0,z,.17,.17,.09,metal,14);rim.rotation.x=Math.PI/2}const rocket=new THREE.Mesh(new THREE.ConeGeometry(.135,.32,10),mat(0xc4a66a,.4,.5));rocket.rotation.x=-Math.PI/2;rocket.position.z=-.88;weaponRig.add(rocket);weaponParts.warhead=rocket;box(weaponRig,0,-.24,.12,.14,.33,.16,metal);box(weaponRig,.18,.21,-.1,.06,.22,.28,metal);box(weaponRig,-.1,-.18,-.4,.2,.19,.2,metal);box(weaponRig,.09,-.3,.23,.18,.2,.24,metal);
 }else{createMeleeWeapon(w);
 }
 if(!w.crossbow)addWeaponDetails(THREE,weaponRig,w);
 muzzle=new THREE.Mesh(new THREE.ConeGeometry(.18,.4,7),new THREE.MeshBasicMaterial({color:0xffc77d,transparent:true,opacity:.8}));muzzle.position.set(0,0,weaponParts.muzzleZ??-1);muzzle.rotation.x=-Math.PI/2;muzzle.visible=false;weaponRig.add(muzzle);muzzleLight=new THREE.PointLight(0xffbc72,0,3);muzzleLight.position.z=weaponParts.muzzleZ??-.8;weaponRig.add(muzzleLight);
}
function createMeleeWeapon(w){
 const shape=w.shape||'knife',length=w.length||.62,metal=0x283b34,steel=w.color||0xc3d3c4,grip=0x71845c;
 box(weaponRig,0,0,.18,.1,.12,.32,metal);box(weaponRig,.03,-.08,.25,.18,.19,.2,metal);box(weaponRig,.12,-.16,.48,.22,.22,.4,0x697e58);
 const shaft=(size,r=.025)=>{const o=cylinder(weaponRig,0,0,-size/2,r,r,size,grip,8);o.rotation.x=Math.PI/2;return o};
 const blade=(size,width=.1,z=-size/2,x=0)=>{const o=new THREE.Mesh(new THREE.ConeGeometry(width,size,4),mat(steel,.8,.25));o.rotation.x=-Math.PI/2;o.scale.z=.23;o.position.set(x,0,z);weaponRig.add(o);return o};
 if(['knife','sword','rapier'].includes(shape)){box(weaponRig,0,0,0,shape==='rapier'?.4:.28,.045,.07,grip);blade(length,shape==='rapier'?.045:shape==='sword'?.12:.085);if(shape==='sword')box(weaponRig,0,.025,-length*.35,.025,.025,length*.6,0xe8efe6)}
 else if(shape==='curved'){const points=[new THREE.Vector3(0,0,0),new THREE.Vector3(.02,0,-length*.4),new THREE.Vector3(.18,0,-length*.82),new THREE.Vector3(.32,0,-length)];weaponRig.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),16,.045,3,false),mat(steel,.8,.25)));box(weaponRig,0,0,0,.23,.045,.06,grip)}
 else if(['axe','halberd'].includes(shape)){shaft(length);box(weaponRig,.12,0,-length*.84,.45,.09,.28,steel,{metal:.7});blade(.32,.15,-length-.06);if(shape==='halberd')blade(.4,.065,-length-.16)}
 else if(shape==='hammer'){shaft(length,.035);box(weaponRig,0,0,-length*.88,.55,.22,.27,steel,{metal:.65});for(const x of [-.29,.29])box(weaponRig,x,0,-length*.88,.07,.25,.31,metal)}
 else if(shape==='bat'){const o=cylinder(weaponRig,0,0,-length/2,.09,.035,length,grip,10);o.rotation.x=Math.PI/2;for(let n=0;n<4;n++)box(weaponRig,0,0,.04+n*.035,.12,.13,.012,metal)}
 else if(shape==='spear'||shape==='trident'){shaft(length);blade(.38,.09,-length-.1);if(shape==='trident')for(const x of [-.17,.17]){box(weaponRig,x/2,0,-length+.1,.2,.05,.055,steel);blade(.28,.055,-length-.06,x)}}
 else if(shape==='staff'){shaft(length,.045);for(const z of [-length,-.05]){const cap=cylinder(weaponRig,0,0,z,.07,.07,.14,steel);cap.rotation.x=Math.PI/2}}
 else if(shape==='scythe'){shaft(length);const b=blade(.85,.16,-length+.05,.32);b.rotation.set(0,0,-Math.PI/2);b.rotation.y=Math.PI/2;box(weaponRig,.14,0,-length,.4,.06,.12,steel)}
 else if(shape==='crowbar'){shaft(length,.035);const bend=new THREE.CatmullRomCurve3([new THREE.Vector3(0,0,-length),new THREE.Vector3(.04,0,-length-.1),new THREE.Vector3(.15,0,-length-.1),new THREE.Vector3(.2,0,-length+.02)]);weaponRig.add(new THREE.Mesh(new THREE.TubeGeometry(bend,12,.035,6,false),mat(steel,.75,.3)))}
}

function slotFor(w){return w.cat==='hg'?1:w.mechanic==='melee'?2:0}
function reconcileLoadout(){const defaults=[0,42,52];quickSlots=defaults.map((id,slot)=>{const saved=quickSlots[slot];return weapons[saved]&&slotFor(weapons[saved])===slot&&services.canUseWeapon(saved)?saved:id});if(!services.canUseWeapon(selectedWeapon))selectedWeapon=quickSlots[0];storage.set('quickSlots',quickSlots)}
function renderQuickSlots(){if(!$('quickSlots'))return;$('quickSlots').innerHTML=quickSlots.map((id,i)=>`<button class="quick-slot ${selectedWeapon===id?'active':''}" data-slot="${i}" aria-label="${i+1}번 ${weapons[id].name}"><kbd>${inputLabel(['primary','sidearm','blade'][i],i+1)}</kbd><b>${weapons[id].name.split(' ').slice(1).join(' ')}</b><small>${['주무기','보조무기','근접'][i]}</small></button>`).join('');$('quickSlots').querySelectorAll('button').forEach(b=>b.onclick=()=>equipQuickSlot(+b.dataset.slot))}
function equipQuickSlot(index){if(!combat||paused||onlineDead)return;const next=quickSlots[index];if(next===selectedWeapon||!services.canUseWeapon(next))return;selectedWeapon=next;inspectedWeapon=next;storage.set('weapon',next);createWeapon();notice(weapons[next].name);sound('select')}
function applyEconomy(){for(const id of ['walletValue','hudCoins'])if($(id))$(id).textContent=services.wallet.coins.toLocaleString()+' C';if(state==='arsenal'){renderArsenal();renderWeaponDetail()}}
function updateCameraLabel(){if($('cameraBtn'))$('cameraBtn').textContent=(viewMode==='third'?'3인칭':'1인칭')+' · V'}
function toggleCamera(){if(!combat||paused)return;viewMode=viewMode==='third'?'first':'third';storage.set('viewMode',viewMode);updateCameraLabel();sound('select')}
function quickMelee(){if(!combat||paused||onlineDead||totalTime<quickMeleeReady)return;const previous=selectedWeapon;quickMeleeReady=totalTime+.9;if(previous===quickSlots[2]){shoot();return}equipQuickSlot(2);quickMeleeAction={previous,weapon:selectedWeapon,attackAt:totalTime+.28,returnAt:totalTime+.72,attacked:false}}
function updateQuickMelee(){const a=quickMeleeAction;if(!a)return;if(onlineDead||selectedWeapon!==a.weapon){quickMeleeAction=null;return}if(totalTime>=a.attackAt&&!a.attacked){a.attacked=true;shoot()}if(totalTime>=a.returnAt){quickMeleeAction=null;if(services.canUseWeapon(a.previous)){selectedWeapon=a.previous;inspectedWeapon=selectedWeapon;createWeapon()}}}
function attackRay(){
 const origin=player.pos.clone().add(new THREE.Vector3(0,player.height,0)),base=new THREE.Vector3(0,0,-1).applyQuaternion(camera.quaternion).normalize();
 if(viewMode==='third'){raycaster.set(camera.position,base);raycaster.far=130;let distance=raycaster.intersectObjects(coverMeshes,false)[0]?.distance??130;const actors=mode==='online'?[...net.players.values()].filter(p=>p.id!==net.id&&p.health>0):enemies.map(e=>({x:e.mesh.position.x,y:e.mesh.position.y,z:e.mesh.position.z,yaw:e.mesh.rotation.y,height:1.7}));for(const actor of actors)distance=Math.min(distance,rayActor(camera.position.toArray(),base.toArray(),actor).distance);const target=camera.position.clone().addScaledVector(base,distance);base.copy(target.sub(origin)).normalize()}
 return {origin,base};
}

function cancelDraw(){if(drawing&&mode==='online')net.send({type:'draw',active:false});drawing=false;if($('chargeMeter'))$('chargeMeter').hidden=true}
function beginAttack(){const w=weapons[selectedWeapon];if(w.mechanic!=='arrow'){shoot();return}if(!combat||paused||onlineDead||reloading>0||shotCooldown>0||mode==='online'&&net.match?.phase!=='playing')return;if(ammo<=0){reload();return}drawing=true;drawStarted=performance.now();$('chargeMeter').hidden=false;if(mode==='online')net.send({type:'draw',active:true})}
function releaseAttack(cancel=false){mouse.down=false;if(!drawing)return;const duration=(performance.now()-drawStarted)/1000,w=weapons[selectedWeapon];drawing=false;$('chargeMeter').hidden=true;if(cancel||duration<.08){if(mode==='online')net.send({type:'draw',active:false});return}shoot(chargePower(duration,w))}
function applyImpulse(velocity){player.vel.add(new THREE.Vector3(...velocity));const speed=Math.hypot(player.vel.x,player.vel.z);if(speed>14.2){player.vel.x*=14.2/speed;player.vel.z*=14.2/speed}player.grounded=false}
function actorList(){return enemies.filter(e=>e.hp>0).map(e=>({id:e.id,x:e.mesh.position.x,y:e.mesh.position.y,z:e.mesh.position.z,height:1.7,yaw:e.mesh.rotation.y,health:e.hp,targetKind:e.targetKind,enemy:e})).concat({id:'local',x:player.pos.x,y:player.pos.y,z:player.pos.z,height:player.height,yaw:player.yaw,health:player.health})}
function makeProjectileVisual(p){if(projectileVisuals.has(p.id))return;const geometry=p.kind==='rocket'?new THREE.ConeGeometry(.075,.35,8):new THREE.CylinderGeometry(.014,.014,.7,5);geometry.rotateX(Math.PI/2);const mesh=new THREE.Mesh(geometry,new THREE.MeshBasicMaterial({color:p.kind==='rocket'?0xffba68:0xd3f878}));mesh.position.fromArray(p.position);mesh.lookAt(mesh.position.clone().add(new THREE.Vector3(...p.velocity)));scene.add(mesh);projectileVisuals.set(p.id,{mesh,position:p.position.slice(),velocity:p.velocity.slice(),gravity:p.gravity})}
function removeProjectileVisual(id){const v=projectileVisuals.get(id);if(!v)return;scene.remove(v.mesh);v.mesh.geometry.dispose();v.mesh.material.dispose();projectileVisuals.delete(id)}
function explosionVisual(position,radius){const mesh=new THREE.Mesh(new THREE.SphereGeometry(radius,12,8),new THREE.MeshBasicMaterial({color:0xffac56,transparent:true,opacity:.28,wireframe:true,depthWrite:false}));mesh.position.fromArray(position);scene.add(mesh);effects.push({mesh,life:.28,max:.28});impact(new THREE.Vector3(...position),0xffbd65)}
function resolvePracticeProjectile(p,hit){const w=weapons[p.weapon],actors=actorList();let hits=[];if(p.kind==='rocket'&&!hit.expired){hits=blastHits(p,w,actors,cover.map(b=>({min:b.min.toArray(),max:b.max.toArray()})),hit.target?.id);explosionVisual(p.position,w.blastRadius)}else if(hit.target)hits=[{target:hit.target,damage:damageForHit(w,hit.head,p.travel)*p.power,head:hit.head,distance:p.travel}];for(const h of hits){if(h.target.id==='local'){if(h.impulse){applyImpulse(h.impulse)}damage(h.damage);continue}const e=h.target.enemy;if(!e||e.hp<=0)continue;e.hp-=h.damage;flashAgent(e.mesh);updateTargetTag(e);hitFeedback(h.damage,h.head,e.hp<=0,new THREE.Vector3(...p.position),h.distance,e.hp);if(e.hp<=0)killEnemy(e,h.head)}}
function updateProjectiles(dt){
 if(mode==='online'){for(const v of projectileVisuals.values()){v.position=v.position.map((n,i)=>n+v.velocity[i]*dt);v.velocity[1]-=v.gravity*dt;v.mesh.position.fromArray(v.position);v.mesh.lookAt(v.mesh.position.clone().add(new THREE.Vector3(...v.velocity)))}return}
 const blocks=cover.map(b=>({min:b.min.toArray(),max:b.max.toArray()})),steps=Math.max(1,Math.ceil(dt/.012));
 for(let step=0;step<steps;step++)for(let i=localProjectiles.length-1;i>=0;i--){const p=localProjectiles[i],hit=stepProjectile(p,dt/steps,blocks,actorList());const visual=projectileVisuals.get(p.id);if(visual){visual.mesh.position.fromArray(p.position);visual.mesh.lookAt(visual.mesh.position.clone().add(new THREE.Vector3(...p.velocity)))}if(hit.done){localProjectiles.splice(i,1);removeProjectileVisual(p.id);resolvePracticeProjectile(p,hit)}}
}
function weaponSvg(w,extra=''){const c=w.cat;if(w.mechanic){const path=w.crossbow?'M15 40L56 20L94 39L86 45L56 31L29 49zM15 54L56 75L94 55L86 49L56 65L29 47zM55 42H166L190 48L166 54H85L99 76H85L72 56H55z':w.mechanic==='arrow'?'M65 8Q135 47 65 87L70 47zM68 44H180V49H68zM178 36L200 47L178 58z':w.mechanic==='rocket'?'M25 31H156L187 47L156 62H25zM71 59H88V84H71zM36 24H49V69H36z':({axe:'M40 85L30 78L115 5L125 15zM85 18Q130 -5 169 10L155 48L111 43z',halberd:'M40 85L30 78L115 5L125 15zM85 18Q130 -5 169 10L155 48L111 43z',hammer:'M45 86L34 76L110 11L121 22zM80 17L102 -2L158 53L136 72z',bat:'M35 80Q29 73 39 65L132 5Q149 -3 159 10Q166 24 150 34L47 83z',spear:'M21 88L15 81L142 20L146 26zM129 22L192 1L157 35z',trident:'M20 88L15 81L135 26L142 33zM114 18L173 1L161 17L130 29L141 44L180 21L192 22L143 59z',staff:'M20 87L14 76L183 2L190 13z',scythe:'M43 90L34 85L104 2L113 7zM106 5Q175 -3 195 58Q162 21 100 22z',crowbar:'M30 85L23 76L149 12Q181 -8 190 18L184 44L173 42L178 20Q173 9 159 21z'}[w.shape]||'M18 57L82 43L175 9L140 53L88 59L32 79z');return `<svg class="${extra}" viewBox="0 0 210 95" fill="currentColor" aria-hidden="true"><path d="${path}"/></svg>`}const body=c==='hg'?'M28 31h62v13H71v27H56V45H28z':c==='sr'?'M13 37h24l9-6h54v-8h19v10h30v5h50v5h-53l-10 9h-30v24H95V53H65L32 67H13z':c==='sg'?'M12 37h35l8-4h78v4h64v9h-69l-11 8H71L41 71H19l13-23H12z':c==='smg'?'M30 32h94l9 7h35v7h-37l-15 8h-14v25H87V53H63L38 66H21l16-24h-7z':c==='lmg'?'M10 34h27l11-8h81v9h64v7h-54l-13 10h-15v24H75V53H59L32 68H13l17-24H10z':'M12 35h30l7-8h73l9 9h63v6h-51l-17 11h-12l-4 24H95l-8-24H64L34 67H13l16-23H12z';return `<svg class="${extra}" viewBox="0 0 210 95" fill="currentColor" aria-hidden="true"><path d="${body}"/><path d="M65 23h35v4H65zM58 31h50v3H58z" opacity=".5"/><path d="M55 40h60v3H55zM51 46h26v3H51z" fill="#111b15" opacity=".6"/><path d="M115 36h9v5h-9z" fill="#d3f878"/></svg>`}
function updateWeaponHud(){const w=weapons[selectedWeapon];$('weaponNameHud').textContent=w.name;$('weaponTypeHud').textContent=categories.find(c=>c.id===w.cat).en;$('ammoValue').innerHTML=w.mechanic==='melee'?'근접':`${ammo}<small>/ ${reserveAmmo}</small>`;$('ammoValue').classList.toggle('empty-ammo',w.mechanic!=='melee'&&ammo===0&&reserveAmmo===0);$('ammoLabel').textContent=w.mechanic==='melee'?`사거리 ${w.reach}m · 초당 ${w.rate}회`:`탄창 ${w.mag} · 예비 ${reserveAmmo} · 남은 총 ${ammo+reserveAmmo}발`;$('weaponDamageHud').textContent=w.mechanic==='melee'?`정면 ${w.damage} · 후면 ${w.backstab?'200 · 한방':Math.round(w.damage*w.backMultiplier*10)/10}`:w.mechanic==='rocket'?`직격 ${w.damage} · 폭발 최대 ${w.splashDamage}`:`몸통 ${w.damage}${w.pellets>1?' × '+w.pellets:''} · 헤드 ${damageForHit(w,true)}${w.pellets>1?' × '+w.pellets:''}`}
function showTab(tab){if(tab==='play'&&combat){resume();return}document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('playPage').hidden=tab!=='play';$('arsenalPage').hidden=tab!=='arsenal';$('recordsPage').hidden=tab!=='records';if(tab==='arsenal'){renderArsenal();renderWeaponDetail()}if(tab==='records')renderRecords();state=tab==='arsenal'?'arsenal':combat?'playing':'lobby'}
function renderMaps(){ $('mapGrid').innerHTML=maps.map((m,i)=>`<button class="map-card ${i===selectedMap?'selected':''}" data-map="${i}" aria-label="${m.ko} 전장 선택" aria-pressed="${i===selectedMap}"><img src="${thumbs[i]||''}" alt="${m.desc}"><span class="map-no">SECTOR 0${i+1}</span><span class="check">✓</span><span class="map-info"><strong>${m.name}</strong><span>${m.desc}</span></span></button>`).join('');$('mapGrid').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(combat)return;buildMap(+b.dataset.map);renderMaps();sound('select')})}
function renderArsenal(){
 $('weaponFilters').innerHTML=categories.map(c=>`<button class="${filter===c.id?'active':''}" data-filter="${c.id}">${c.name}${c.id==='all'?' '+weapons.length:''}</button>`).join('');$('weaponFilters').querySelectorAll('button').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderArsenal()});
 $('weaponGrid').innerHTML=weapons.filter(w=>filter==='all'||w.cat===filter).map(w=>`<button class="weapon-card ${w.id===inspectedWeapon?'selected':''} ${services.canUseWeapon(w.id)?'':'locked'}" data-weapon="${w.id}" aria-label="${w.name} 상세 정보"><span>${categories.find(c=>c.id===w.cat).en}${w.oneShot?' · ONE SHOT':''}</span>${weaponSvg(w)}<strong>${w.name}</strong><small>${w.mechanic==='melee'?w.ko+' / '+w.reach+'m':w.mag+' + '+w.reserve+' 발'}</small><em class="weapon-price">${services.canUseWeapon(w.id)?'보유 중':weaponPrice(w.id)+' C'}</em>${w.id===selectedWeapon?'<b class="equipped">장착 중</b>':''}</button>`).join('');$('weaponGrid').querySelectorAll('button').forEach(b=>b.onclick=()=>{inspectedWeapon=+b.dataset.weapon;renderArsenal();renderWeaponDetail();sound('select')});
}
function renderWeaponDetail(){
 const w=weapons[inspectedWeapon],category=categories.find(c=>c.id===w.cat),owned=services.canUseWeapon(w.id);
 $('weaponDetail').innerHTML=`<div class="eyebrow">${category.en}${w.oneShot?' · ONE SHOT':''}</div><h2>${w.name.split(' ').slice(1).join(' ')}</h2><span class="weapon-sub">${w.name.split(' ')[0]} · ${w.ko||category.name}</span>${weaponSvg(w,'weapon-illustration')}<p>${w.oneShot?'몸통 한 발로 200 HP를 제압합니다. 단발 탄창과 긴 재장전으로 신중하게 발사하세요.':w.mechanic==='melee'?meleeDescription(w)+'<br>F 빠른 근접 · 정면은 베기, 후면은 찌르기. 등 뒤 중앙 120°에서 후면 판정.':w.crossbow?'탄시위를 미리 걸어 두는 석궁입니다. 클릭하면 즉시 볼트를 발사하며 재장전할 때 장전합니다.':w.mobility?sidearmDescription(w):w.mechanic==='arrow'?'왼쪽 버튼을 당겼다가 놓아 화살을 발사합니다.':'서로 다른 반동·피해량·장탄수를 가진 무기를 구매해 장비하세요.'}</p><div class="damage-comparison"><div><span>${w.mechanic==='melee'?'정면 몸통':'몸통'}</span><b>${w.damage}${w.pellets>1?' × '+w.pellets:''}</b></div><div><span>헤드</span><b>${damageForHit(w,true)}${w.pellets>1?' × '+w.pellets:''}</b></div></div><p class="damage-note">헤드 배율 ×${w.headMultiplier} · ${w.rangeStart}m부터 피해 감소<br>${w.mechanic==='melee'?'사거리 '+w.reach+'m · 후면 '+(w.backstab?'200 피해 · 한방':Math.round(w.damage*w.backMultiplier*10)/10+' 피해 (×'+w.backMultiplier+')'):w.rangeEnd+'m 이후 기본 피해의 '+Math.round(w.minDamage*100)+'%'}</p><div class="weapon-specs">${w.mechanic==='melee'?`<span>공격 간격<b>${(1/w.rate).toFixed(2)}초</b></span><span>사거리<b>${w.reach}m</b></span>`:`<span>탄창<b>${w.mag}발</b></span><span>예비 탄약<b>${w.reserve}발</b></span><span>초기 총 탄약<b>${w.mag+w.reserve}발</b></span><span>재장전<b>${w.reload.toFixed(2)}초</b></span>`}</div><div class="store-balance">보유 ${services.wallet.coins.toLocaleString()} C · ${owned?'구매 완료':weaponPrice(w.id)+' C'}</div><button class="primary" id="equipBtn">${owned?'장착'+(combat?'하고 복귀':''):'구매하고 장착 · '+weaponPrice(w.id)+' C'}<span>↗</span></button>`;
 $('equipBtn').onclick=async()=>{try{if(!services.canUseWeapon(w.id))await services.buyWeapon(w.id);selectedWeapon=w.id;quickSlots[slotFor(w)]=w.id;storage.set('quickSlots',quickSlots);storage.set('weapon',selectedWeapon);createWeapon();sound('select');if(combat){$('lobby').hidden=true;resume()}else{renderArsenal();renderWeaponDetail();toast(w.name+' 장착 완료')}}catch(error){toast(error.message)}};
}
function renderRecords(){const sum=records.reduce((a,r)=>({kills:a.kills+r.kills,score:Math.max(a.score,r.score),wave:Math.max(a.wave,r.wave)}),{kills:0,score:0,wave:0});$('careerStats').innerHTML=[['총 출격',records.length],['누적 처치',sum.kills],['최고 점수',sum.score.toLocaleString()],['최고 웨이브',String(sum.wave).padStart(2,'0')]].map(([n,v])=>`<div><span>${n}</span><b>${v}</b></div>`).join('');$('profileLevel').textContent=String(services.profile.level).padStart(2,'0');$('recordTable').innerHTML=records.length?`<div class="record-head"><span>날짜</span><span>전장</span><span>모드</span><span>처치 / 점수</span><span>생존 시간</span></div>${records.slice().reverse().slice(0,12).map(r=>`<div class="record-row"><span>${new Date(r.date).toLocaleDateString('ko-KR',{month:'2-digit',day:'2-digit'})}</span><span>${maps[r.map].name}</span><span>${r.mode==='waves'?'웨이브 '+r.wave:r.mode==='timed'?'타임 어택':r.mode==='online'?((/^[1-4]v[1-4]$/.test(r.matchMode||'')?r.matchMode:'온라인')+(r.outcome==='win'?' 승':r.outcome==='loss'?' 패':r.outcome==='draw'?' 무':'')):r.mode==='bots'?'봇 연습':'고정 표적'}</span><span>${r.kills} / ${r.score.toLocaleString()}</span><span>${formatTime(r.time)}</span></div>`).join('')}`:'<div class="empty-records">아직 전투 기록이 없습니다. 첫 번째 전장에 뛰어들어 보세요.</div>'}
function formatTime(t){return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`}
function announce(text,sub='',duration=3){$('announcement').innerHTML=text+(sub?`<small>${sub}</small>`:'');announcementTime=duration;$('announcement').style.opacity=1}
function validPosition(x,z,r=.6){if(Math.abs(x)>26||Math.abs(z)>26)return false;return !cover.some(b=>x>b.min.x-r&&x<b.max.x+r&&z>b.min.z-r&&z<b.max.z+r&&b.max.y>.5)}
function updateTargetTag(e){if(!e.tag)return;const c=e.tag.userData.canvas,ctx=c.getContext('2d');ctx.clearRect(0,0,256,64);ctx.fillStyle='#112018dd';ctx.fillRect(0,0,256,64);ctx.fillStyle='#e7f6d6';ctx.font='600 20px sans-serif';ctx.textAlign='center';ctx.fillText(`TARGET  ${Math.max(0,Math.ceil(e.hp))} / ${e.maxHp}`,128,27);ctx.fillStyle='#57644b';ctx.fillRect(20,43,216,5);ctx.fillStyle='#d3f878';ctx.fillRect(20,43,216*Math.max(0,e.hp/e.maxHp),5);e.tag.material.map.needsUpdate=true}
function spawnEnemy(training=false){let x,z;for(let tries=0;tries<100;tries++){x=rand(-23,23);z=rand(-23,13);if(validPosition(x,z,.6)&&Math.hypot(x-player.pos.x,z-player.pos.z)>12)break}if(!validPosition(x,z,.6)){x=0;z=-22}if(training){const lanes=[[0,11],[-6,10],[6,10],[-6,-5],[4,-9],[3,-22]];for(let n=0;n<lanes.length;n++){const spot=lanes[n];if(validPosition(...spot,.6)&&!enemies.some(e=>e.training&&Math.hypot(e.mesh.position.x-spot[0],e.mesh.position.z-spot[1])<1)){[x,z]=spot;break}}}const model=makeAgent(training?0x8bba9d:wave>3?0xa69a7b:0x858e81,true);model.position.set(x,0,z);const multiplier=mode==='bots'?{easy:.7,normal:1,hard:1.5}[practice.difficulty]:1;const hp=BOT_MAX_HEALTH;const e={id:crypto.randomUUID(),mesh:model,hp,maxHp:hp,speed:training?0:(1.2+Math.min(wave*.16,1.8))*multiplier,cooldown:rand(1,3),phase:rand(0,6),strafe:Math.random()>.5?1:-1,turn:0,flash:0,training,multiplier};model.traverse(o=>{if(o.isMesh)o.userData.enemy=e});if(training){const canvas=document.createElement('canvas');canvas.width=256;canvas.height=64;const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;const tag=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,transparent:true,depthTest:true}));tag.position.set(0,2.6,0);tag.scale.set(1.8,.45,1);tag.userData.canvas=canvas;tag.raycast=()=>{};model.add(tag);e.tag=tag;updateTargetTag(e)}worldGroup.add(model);enemies.push(e)}
function startWave(){const n=Math.min(3+wave*2,16);for(let i=0;i<n;i++)spawnEnemy();waveDelay=0;$('waveLabel').textContent='WAVE '+String(wave).padStart(2,'0');announce('WAVE '+String(wave).padStart(2,'0'),`${n}기의 적을 제압하세요`)}
function completeWave(){clearBotShots();waveDelay=3;player.health=MAX_HEALTH;refillAllAmmo();score+=wave*100;announce('SECTOR CLEAR',`웨이브 ${wave} 완료 · 체력 200 · 탄창·예비탄 완충`,2.7);services.rewardWave(wave,kills).then(amount=>{if(amount)notice('웨이브 보상 +'+amount+' C · 체력 200 · 탄약 완충')}).catch(error=>toast(error.message));updateHud()}

function startGame(requestedMode=null){
 initAudio();reconcileLoadout();quickMeleeAction=null;quickMeleeReady=0;const next=typeof requestedMode==='string'?requestedMode:$('modeSelect').value;if(next!=='online')net.leave();mode=next;if(mode==='online'){selectedMap=onlineWelcome.map;if(adminEnabled)net.send({type:'adminCheats',flags:adminCheats})}if(mode!=='hub'&&mode!=='online')hubSession=false;
 combat=true;paused=false;state='playing';pointerFallback=false;lockPointer();
 magazineInventory.clear();reserveInventory.clear();rigWeapon=null;buildMap(selectedMap);localAvatar=makeAgent(0x8ca9a7);worldGroup.add(localAvatar);lobbyAgent.visible=false;combat=true;paused=false;state='playing';totalTime=0;kills=0;score=0;wave=1;waveDelay=0;respawns=[];onlineDead=false;onlineSeq=0;pendingOnlineShots=[];actionSeq=0;pendingEquip=0;pendingReload=0;networkClock=0;myTeam=null;onlineResultHandled=false;matchNoticeKey='';$('resultProgress').hidden=true;$('resultStats').classList.remove('match-result-stats');$('retryBtn').innerHTML='다시 도전 <span>→</span>';$('restartBtn').innerHTML=mode==='online'?'경기 모드 다시 선택 <span>↻</span>':'전투 다시 시작 <span>↻</span>';
 practice={count:Number($('botCount').value),difficulty:$('botDifficulty').value,invincible:$('botInvincible').checked};
 player.pos.set(0,0,19);player.vel.set(0,0,0);player.yaw=0;player.pitch=0;player.height=1.7;player.health=MAX_HEALTH;player.meleeReadyAt=0;player.meleeAbilityReadyAt=0;player.backstabReadyUntil=0;player.meleeExtraJumpsUntil=0;player.stunUntil=0;player.jumps=0;player.grounded=true;player.slide=0;player.slideCooldown=0;recoil=0;kick=0;shotCooldown=.3;aim=false;shotIndex=0;resetMotion();
 if(mode==='online'){const p=onlineWelcome.self;player.pos.set(p.x,p.y,p.z);player.yaw=p.yaw;player.health=p.health;kills=p.kills;score=kills*100;myTeam=p.team;}
 createWeapon();keys.clear();mouse.down=false;$('movementState').textContent='OPERATOR ONLINE';$('killFeed').replaceChildren();$('lobby').hidden=true;$('hud').hidden=false;$('pauseOverlay').hidden=true;$('resultOverlay').hidden=true;$('onlineScoreboard').hidden=true;document.body.classList.add('playing');document.body.classList.toggle('online-game',mode==='online');$('onlineHud').hidden=mode!=='online';$('touchUi').hidden=!isTouch;$('refillAmmo').hidden=!['bots','training','hub'].includes(mode);
 $('hudMode').style.color='var(--lime)';$('hudMode').textContent={waves:'WAVE SURVIVAL',timed:'TIME ATTACK',training:'TARGET RANGE',bots:'AI BOT PRACTICE',online:'ONLINE DEATHMATCH',hub:'VECTOR ATRIUM'}[mode];
 $('pauseOverlay').querySelector('p').textContent=mode==='online'?'온라인 경기는 계속됩니다. 경기 중 나가면 기권패가 기록됩니다.':'다시 뛰어들 준비가 되셨나요?';
 updateCameraLabel();if(mode==='hub'){buildHub(THREE,worldGroup,{box,cylinder,wallText,mat});spawnHubStations();$('refillAmmo').hidden=false;$('waveLabel').textContent='HIDDEN ATRIUM';announce('VECTOR ATRIUM','듀얼 패드 · 고정 봇 · 사격 표적')}else if(mode==='waves'){services.beginWaves();startWave()}else if(mode==='online'){$('waveLabel').textContent='WAITING';announce('TEAM LOBBY',`ROOM ${net.room} · 인원이 모이면 자동으로 시작합니다`)}else{const n=mode==='bots'?practice.count:6;for(let i=0;i<n;i++)spawnEnemy(mode==='training');$('waveLabel').textContent=mode==='training'?'TARGET RANGE':mode==='bots'?'BOT PRACTICE':'03:00';announce(mode==='training'?'TARGET RANGE':mode==='bots'?'BOT PRACTICE':'TIME ATTACK',mode==='training'?'몸통·헤드 피해량 비교 · 표적 100 HP':mode==='bots'?`${n}기 AI 봇 · ${{easy:'쉬움',normal:'보통',hard:'어려움'}[practice.difficulty]} · ${practice.invincible?'무적 ON':'실전 체력'}`:'3분 안에 최대한 많은 적을 처치하세요')}
 updateHud();lockPointer();
}
function syncMouseMode(){syncAudioScene();const active=combat&&!paused&&state==='playing'&&!isTouch;document.body.classList.toggle('mouse-look',active);$('mouseCaptureHint').hidden=!active||!pointerFallback||document.pointerLockElement===$('world')}
function enablePointerFallback(){pointerLockPending=false;if(document.pointerLockElement===$('world'))return;pointerFallback=true;resetMouseLook(mouse);syncMouseMode();if(combat&&!paused&&!pointerHintShown){pointerHintShown=true;toast('화면을 클릭하면 마우스 고정 · 360° 조준 · ESC 메뉴')}}
function handlePointerLockChange(){pointerLockPending=false;resetMouseLook(mouse);if(document.pointerLockElement===$('world')){if(!combat||paused||state!=='playing'){document.exitPointerLock();syncMouseMode();return}pointerFallback=false}else if(combat&&!paused&&!isTouch)enablePointerFallback();syncMouseMode()}
function lockPointer(){
 syncMouseMode();if(isTouch||!combat||paused||pointerLockPending||document.pointerLockElement===$('world'))return;
 resetMouseLook(mouse);const canvas=$('world');pointerLockPending=true;
 requestMouseLock(canvas,document).then(locked=>{pointerLockPending=false;if(locked)handlePointerLockChange();else enablePointerFallback()});
}

function handleMouseLook(e){
 if(!combat||paused||isTouch)return;
 const locked=document.pointerLockElement===$('world');if(!locked&&!pointerFallback)return;
 if(!locked&&e.target!==$('world')){resetMouseLook(mouse);return}
 const [dx,dy]=mouseLookDelta(mouse,e,locked);applyMouseLook(dx,dy);
}
function applyMouseLook(dx,dy){const sens=.002*settings.sensitivity*(aim?.55:1);mouse.dx+=dx;mouse.dy+=dy;player.yaw-=dx*sens;player.pitch=clamp(player.pitch-dy*sens,-1.45,1.45)}
function pause(){if(!combat||paused)return;cancelDraw();paused=true;state='paused';syncMouseMode();keys.clear();mouse.down=false;resetMouseLook(mouse);aim=false;if(document.pointerLockElement)document.exitPointerLock();$('pauseOverlay').hidden=false}
function resume(){if(!combat)return;paused=false;state='playing';$('pauseOverlay').hidden=true;$('lobby').hidden=true;$('hud').hidden=false;keys.clear();mouse.down=false;shotCooldown=.2;lockPointer()}
function saveRecord(){if(mode==='online'||mode==='hub')return;const record={id:crypto.randomUUID?.()||String(Date.now())+Math.random().toString(36).slice(2),date:Date.now(),map:selectedMap,mode,kills,score,wave,time:Math.floor(totalTime)};records.push(record);records=records.slice(-200);storage.set(services.account?'records:'+services.account.username:'records',records);services.saveRecord(record);renderRecords()}
function returnLobby(save=true){if(combat&&save)saveRecord();const fromHub=mode==='hub'||hubSession;hubGeneration++;hubSession=false;hubPadState={id:null,time:0,started:false};hubRespawns=[];jumpSlideCancel();net.leave();combat=false;paused=true;state='lobby';if(fromHub)selectedMap=hubReturnMap;syncMouseMode();if(document.pointerLockElement)document.exitPointerLock();keys.clear();mouse.down=false;aim=false;$('pauseOverlay').hidden=true;$('resultOverlay').hidden=true;$('hud').hidden=true;$('lobby').hidden=false;document.body.classList.remove('playing');buildMap(selectedMap);showTab('play');renderMaps()}
function finish(victory=false){if(!combat)return;paused=true;state='result';syncMouseMode();keys.clear();mouse.down=false;if(document.pointerLockElement)document.exitPointerLock();saveRecord();$('resultOverlay').hidden=false;$('resultTitle').textContent=mode==='timed'?'작전 완료.':mode==='bots'?'훈련 종료.':'다음 전선으로.';$('resultMessage').textContent=mode==='timed'?'3분의 전투, 당신의 기록이 남았습니다.':mode==='bots'?`${kills}기의 AI 봇을 제압했습니다. 설정을 바꾸어 다시 연습해 보세요.`:`${wave}번째 웨이브까지 버텼습니다. 다시 한 번 한계를 넘어보세요.`;$('resultStats').innerHTML=[['처치',kills],['점수',score.toLocaleString()],['생존 시간',formatTime(totalTime)]].map(([n,v])=>`<span>${n}<b>${v}</b></span>`).join('')}
function reload(){const w=weapons[selectedWeapon];if(!combat||paused||onlineDead||reloading>0||ammo===w.mag||w.mechanic==='melee')return;if(reserveAmmo<=0){if(shotCooldown<=0){notice(mode==='bots'||mode==='training'?'탄약 소진 · T 탄약 보충':'탄약 소진 · 다른 무기를 선택하세요');sound('select');shotCooldown=.4}return}cancelDraw();reloading=w.reload;aim=false;if(mode==='online'){pendingReload=++actionSeq;net.send({type:'reload',seq:pendingReload})}sound('reload');$('reloadHint').textContent='재장전 중…'}
function completeWeaponReload(){
 if(mode==='online'){reloading=.001;return}
 const next=refillMagazine(weapons[selectedWeapon],ammo,reserveAmmo);ammo=next.ammo;reserveAmmo=next.reserve;magazineInventory.set(selectedWeapon,ammo);reserveInventory.set(selectedWeapon,reserveAmmo);reloading=0;updateWeaponHud();$('reloadHint').innerHTML='R 재장전 · 1~3 무기 전환 · B 무기고';sound('reload');
}
function refillAllAmmo(){cancelDraw();for(const id of new Set([...magazineInventory.keys(),...quickSlots,selectedWeapon])){const w=weapons[id];if(!w)continue;magazineInventory.set(id,w.mag);reserveInventory.set(id,w.reserve)}const w=weapons[selectedWeapon];ammo=w.mag;reserveAmmo=w.reserve;reloading=0;pendingReload=0;updateWeaponHud()}
function refillPracticeAmmo(){if(!combat||paused||!['bots','training','hub'].includes(mode))return;refillAllAmmo();notice('모든 훈련 탄약 보충 완료');sound('reload')}
function isPlayerStunned(){return mode==='online'?(net.players.get(net.id)?.stunUntil||0)>net.serverNow:(player.stunUntil||0)>totalTime}
function applyLocalMeleePerk(w,e,actualDamage){const perk=activateMeleePerk(w,player,totalTime*1000);if(!perk)return;if(perk.heal)player.health=Math.min(MAX_HEALTH,player.health+Math.min(perk.heal,actualDamage));if(perk.stun&&e.hp>0)e.stunUntil=totalTime+perk.stun;if(perk.ammoFraction){for(const id of new Set([...magazineInventory.keys(),...quickSlots])){const gun=weapons[id];if(!gun||gun.mechanic==='melee')continue;const next=restoreMeleeAmmo(gun,magazineInventory.get(id)??gun.mag,reserveInventory.get(id)??gun.reserve,perk.ammoFraction);magazineInventory.set(id,next.ammo);reserveInventory.set(id,next.reserve)}}notice(perk.title+' 발동');updateMeleeHud()}
function updateMeleeHud(){const w=weapons[quickSlots[2]],remaining=Math.max(0,((player.meleeAbilityReadyAt||0)-(mode==='online'?net.serverNow:Date.now()))/1000);$('meleePerkHud').textContent=(isPlayerStunned()?'기절 중 · ':'')+w.ability.title+' · 우클릭 / E '+(remaining>0?remaining.toFixed(1)+'초':'준비됨')}

function dash(){activateMeleeAbilityAction()}
function activateMeleeAbilityAction(){
 if(!combat||paused||onlineDead||isPlayerStunned())return;const w=weapons[selectedWeapon];if(w.mechanic!=='melee'){notice('근접무기를 장착하세요');return}
 const now=mode==='online'?net.serverNow:Date.now(),ability=activateMeleeAbility(w,player,now);if(!ability){notice('특수 능력 재사용 대기 중');return}
 if(mode==='online'){net.send({type:'meleeAbility'});updateMeleeHud();return}
 if(ability.kind==='backstab')player.backstabReadyUntil=Date.now()+9000;
 else if(ability.kind==='tripleJump'){player.meleeExtraJumpsUntil=Date.now()+3000;notice('3초 동안 3단 점프')}
 else if(ability.kind==='skyDash'){const dir=new THREE.Vector3(-Math.sin(player.yaw),0,-Math.cos(player.yaw));player.vel.x=dir.x*11;player.vel.z=dir.z*11;player.vel.y=15;player.grounded=false;notice('상승 대시!');sound('dash')}
 else if(ability.kind==='heal'){player.health=Math.min(MAX_HEALTH,player.health+ability.amount);notice('체력 +'+ability.amount)}
 else if(ability.kind==='reload'){for(const id of new Set([...quickSlots,...magazineInventory.keys()])){const gun=weapons[id];if(gun?.mechanic==='melee')continue;const next=restoreMeleeAmmo(gun,magazineInventory.get(id)??gun.mag,reserveInventory.get(id)??gun.reserve,ability.fraction);magazineInventory.set(id,next.ammo);reserveInventory.set(id,next.reserve)}notice('주무기와 보조무기 탄약 보급')}
 else if(ability.kind==='stun'){const {origin,base}=attackRay();let chosen=null,best=ability.range;for(const e of enemies){if(e.hp<=0)continue;const hit=rayActor(origin.toArray(),base.toArray(),{x:e.mesh.position.x,y:e.mesh.position.y,z:e.mesh.position.z,yaw:e.mesh.rotation.y,height:1.7});if(hit.distance<best){best=hit.distance;chosen=e}}if(chosen){chosen.stunUntil=totalTime+ability.duration;notice('충격파 · '+chosen.stunUntil.toFixed(1))}else{player.meleeAbilityReadyAt=now;notice('사거리 안에 상대가 없습니다');return}}
 updateMeleeHud();updateHud()
}
function applyOnlineMeleeAbility(m){if(m.id!==net.id)return;player.meleeAbilityReadyAt=m.readyAt||0;player.health=m.health??player.health;if(m.kind==='backstab')player.backstabReadyUntil=m.backstabReadyUntil||Date.now()+9000;if(m.kind==='tripleJump')player.meleeExtraJumpsUntil=m.extraJumpsUntil||Date.now()+3000;if(m.kind==='skyDash'){player.vel.x=m.velocity?.[0]||0;player.vel.y=m.velocity?.[1]||15;player.vel.z=m.velocity?.[2]||0;player.grounded=false;sound('dash')}for(const row of m.inventory||[]){magazineInventory.set(row.weapon,row.ammo);reserveInventory.set(row.weapon,row.reserve)}if(m.stunned)notice('충격파 적중');else notice(m.title||'특수 능력 발동');updateWeaponHud();updateMeleeHud()}
function handleDashAck(m){if(!combat||mode!=='online'||m.seq!==pendingDash)return;pendingDash=0;player.dashCooldown=Math.max(0,(m.readyAt-net.serverNow)/1000);if(!m.accepted){player.dash=0;player.vel.x=0;player.vel.z=0;player.pos.set(m.x,m.y,m.z);return}player.dash=Math.max(0,(m.until-net.serverNow)/1000);player.dashSpeed=m.speed;player.dashDir??=new THREE.Vector3();player.dashDir.set(m.direction[0],0,m.direction[1])}
function updateMobilityHud(){const w=weapons[selectedWeapon],node=$('mobilityHud');node.hidden=!w.mobility;node.textContent=w.mobility?(w.extraJumps?'보조무기 장착 중 공중 점프 +1':''):' ';$('touchMeleeAbility').hidden=w.mechanic!=='melee';$('touchMeleeAbility').textContent=w.mechanic==='melee'?'특수':''}
function jump(){if(!combat||paused||onlineDead)return;player.jumpBuffer=.14}
function slide(){if(!combat||paused||onlineDead)return false;const ok=startSlide(player);if(ok){notice('SLIDE');sound('slide')}return ok}
function canTouchSlide(){return combat&&!paused&&!onlineDead&&player.grounded&&player.speed>3&&player.slide<=0}
function notice(t){$('pickupNotice').textContent=t;$('pickupNotice').style.opacity=1;noticeTime=1.1}
function addLine(from,to,color=0xffdb97,life=.065){const geo=new THREE.BufferGeometry().setFromPoints([from.clone(),to.clone()]);const mesh=new THREE.Line(geo,new THREE.LineBasicMaterial({color,transparent:true,opacity:.8}));scene.add(mesh);effects.push({mesh,life,max:life})}
function impact(pos,color){for(let n=0;n<3;n++){const mesh=new THREE.Mesh(new THREE.SphereGeometry(.035,4,4),new THREE.MeshBasicMaterial({color}));mesh.position.copy(pos);scene.add(mesh);effects.push({mesh,life:.22,max:.22,vel:new THREE.Vector3(rand(-2,2),rand(1,3),rand(-2,2))})}}
function hitFeedback(amount,head,killed,point,distance,health,label=null){
 hitTime=killed?.25:.16;$('hitmarker').classList.toggle('kill',killed);$('hitmarker').classList.toggle('head',head);
 const node=document.createElement('span');node.className='damage-number'+(head?' head':'')+(killed?' lethal':'');node.textContent=(head?'⌖ ':'')+(Math.round(amount*10)/10);$('damageNumbers').append(node);
 if(floatingDamage.length>=16)floatingDamage.shift().node.remove();floatingDamage.push({node,point:point.clone(),life:1,max:1});
 $('lastHit').hidden=false;$('lastHit').classList.toggle('head',head);$('lastHit').innerHTML=`<span>${label||(head?'HEADSHOT':'BODY HIT')}${killed?' · ELIMINATED':''}</span><b>${Math.round(amount*10)/10}<small> DMG</small></b><em>${distance.toFixed(1)}m · 남은 체력 ${Math.max(0,Math.ceil(health))}</em>`;
 sound(killed?'kill':'hit');
}
function shoot(power=1){
 if(adminEnabled&&adminCheats.ammo&&ammo<=0)ammo=weapons[selectedWeapon].mag;
 if(!combat||paused||onlineDead||mode==='online'&&net.match?.phase!=='playing'||reloading>0||shotCooldown>0||isPlayerStunned())return;if(ammo<=0){reload();return}
 const w=weapons[selectedWeapon];if(w.mechanic!=='melee'&&!adminCheats.ammo)ammo--;meleeSwing=w.mechanic==='melee'?(w.swingTime||.28):0;meleeBackSwing=false;shotCooldown=1/w.rate;motion.shotTime=0;shotIndex++;
 recoil=Math.min(.24,recoil+w.recoil*(aim?.65:1));motion.recoilSide+=w.sideRecoil*(shotIndex%3===0?-1:1);motion.kickVelocity+=w.kick*54;muzzleTime=(!w.mechanic||w.mechanic==='rocket')?.045:0;muzzle.rotation.z=Math.random()*6;muzzle.visible=true;muzzleLight.intensity=5;sound('shot');
 camera.updateMatrixWorld();const {origin,base}=attackRay();if(localAvatar)fireAgent(localAvatar);
 if(mode==='online'){sendNetworkPosition();const seq=++onlineSeq;pendingOnlineShots.push(seq);net.send({type:'shoot',dir:base.toArray(),aim,seq});updateWeaponHud();if(ammo<=0)setTimeout(()=>{if(combat&&!paused&&ammo===0)reload()},260);return}
 if(w.projectileSpeed){const p=makeProjectile('local-'+(++projectileSeq),'local',w,origin.toArray(),base.toArray(),power);localProjectiles.push(p);makeProjectileVisual(p);updateWeaponHud();if(ammo<=0)setTimeout(()=>{if(combat&&!paused&&ammo===0)reload()},180);return}
 const directions=shotDirections(base.toArray(),w,{aim,grounded:player.grounded,speed:player.speed,crouched:player.height<1.4});const hitsByEnemy=new Map();
 for(let pellet=0;pellet<directions.length;pellet++){
  const dir=new THREE.Vector3(...directions[pellet]);raycaster.set(origin,dir);raycaster.far=130;const worldHit=raycaster.intersectObjects(coverMeshes,false)[0];let distance=Math.min(worldHit?.distance??130,w.reach||130),target=null,head=false;
  for(const e of enemies){if(e.hp<=0)continue;const hit=rayActor(origin.toArray(),directions[pellet],{x:e.mesh.position.x,y:e.mesh.position.y,z:e.mesh.position.z,yaw:e.mesh.rotation.y,height:1.7,targetKind:e.targetKind});if(hit.distance<distance){distance=hit.distance;target=e;head=hit.head}}
  const point=origin.clone().addScaledVector(dir,distance);
  if(target){const hit=hitsByEnemy.get(target)||{amount:0,head:false,point,distance};if(w.mechanic==='melee'){const strike=meleeHit(w,head,distance,origin.toArray(),{x:target.mesh.position.x,z:target.mesh.position.z,yaw:target.mesh.rotation.y+Math.PI},player);hit.amount+=strike.damage;hit.rear=strike.rear;hit.execution=strike.execution;meleeBackSwing=strike.rear}else hit.amount+=damageForHit(w,head,distance);hit.head||=head;hitsByEnemy.set(target,hit);if(pellet<3)impact(point,head?0xd3f878:0xffc97b)}else if(worldHit&&worldHit.distance<=(w.reach||130)&&pellet<2)impact(point,0xe8dbb0);
  if(pellet<2&&w.mechanic!=='melee'){const start=origin.clone().addScaledVector(dir,.9).add(new THREE.Vector3(.12,-.14,0).applyQuaternion(camera.quaternion));addLine(start,point,w.cat==='sr'?0xd7ffb7:0xffe6ad)}
 }
 for(const[e,h]of hitsByEnemy){const actual=Math.min(e.hp,h.amount);e.hp-=h.amount;if(w.mechanic==='melee'){applyLocalMeleePerk(w,e,actual);if(h.execution)player.backstabReadyUntil=0;}flashAgent(e.mesh);updateTargetTag(e);const killed=e.hp<=0;hitFeedback(h.amount,h.head,killed,h.point,h.distance,e.hp,h.execution?'BACKSTAB':h.rear?'REAR HIT':null);if(killed)killEnemy(e,h.head)}
 updateWeaponHud();if(ammo<=0)setTimeout(()=>{if(combat&&!paused&&ammo===0)reload()},260);
}
function killEnemy(e,head){const idx=enemies.indexOf(e);if(idx<0)return;enemies.splice(idx,1);retireAgent(e.mesh);kills++;const gain=(head?150:100)+wave*10;score+=gain;player.health=Math.min(MAX_HEALTH,player.health+5);hitTime=.23;const f=document.createElement('div');f.innerHTML=`<b>${head?'HEADSHOT':'ELIMINATED'}</b> SENTINEL · +${gain}`;$('killFeed').prepend(f);setTimeout(()=>f.remove(),3100);notice(head?`HEADSHOT +${gain} · HP +5`:`ELIMINATION +${gain} · HP +5`);if(mode==='hub')hubRespawns.push({at:totalTime+3,station:e.hubStation});else if(mode!=='waves')respawns.push(totalTime+1);updateHud()}
function lineOfSight(from,to){const delta=to.clone().sub(from);const dist=delta.length();const ray=new THREE.Ray(from,delta.normalize());return !cover.some(b=>{const h=ray.intersectBox(b,new THREE.Vector3());return h&&h.distanceTo(from)<dist-.5})}
function damage(amount){if(player.health<=0)return;damageOpacity=.8;sound('hurt');if(adminEnabled&&(adminCheats.health||adminCheats.evasion&&Math.random()<.8)||mode==='training'||mode==='hub'||mode==='bots'&&practice.invincible)return;player.health=Math.max(0,player.health-amount);damageOpacity=.8;player.land=.05;updateHud();if(player.health<=0)finish()}
function clearBotShots(){for(const p of botProjectiles){scene?.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose()}botProjectiles.length=0}
function launchBotShot(plan,owner){if(botProjectiles.length>=BOT_SHOT_LIMIT)return;const p=createBotShot(plan,'bot-'+(++botShotSeq),owner),geometry=new THREE.CylinderGeometry(.035,.035,.6,5);geometry.rotateX(Math.PI/2);p.mesh=new THREE.Mesh(geometry,new THREE.MeshBasicMaterial({color:0xffbd68}));p.mesh.position.fromArray(p.position);p.mesh.lookAt(p.mesh.position.clone().add(new THREE.Vector3(...p.velocity)));scene.add(p.mesh);botProjectiles.push(p)}
function updateBotProjectiles(dt){for(let i=botProjectiles.length-1;i>=0;i--){const p=botProjectiles[i],result=stepBotShot(p,dt,cover,{x:player.pos.x,y:player.pos.y,z:player.pos.z,height:player.height,yaw:player.yaw,health:player.health});p.mesh.position.fromArray(p.position);if(!result.done)continue;scene.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose();botProjectiles.splice(i,1);if(result.hit){damage(result.damage);if(paused)break}else if(result.wall)impact(new THREE.Vector3(...p.position),0xffcf8a)}}
function updateEnemies(dt){for(const e of enemies){
 e.mesh.userData.poseState={phase:e.phase,moveSpeed:e.shotPlan||e.training?0:e.speed,hitTime:e.mesh.userData.hitTime};const aimPitch=Math.atan2(player.pos.y+player.height-(e.mesh.position.y+1.22),Math.max(1,player.pos.distanceTo(e.mesh.position)));animateAgent(e.mesh,dt,-aimPitch);
 if(e.targetKind){animateAgent(e.mesh,dt);continue}
 if(totalTime<(e.stunUntil||0)){e.shotPlan=null;e.mesh.userData.flash.visible=false;e.mesh.userData.legs.forEach(l=>l.rotation.x=exp(l.rotation.x,0,12,dt));continue}
 e.phase+=dt*(e.speed*3+1);const dir=v3.copy(player.pos).sub(e.mesh.position),dist=dir.length(),angle=e.shotPlan?Math.atan2(e.shotPlan.direction[0],e.shotPlan.direction[2]):Math.atan2(dir.x,dir.z);let da=angle-e.mesh.rotation.y;while(da>Math.PI)da-=Math.PI*2;while(da<-Math.PI)da+=Math.PI*2;if(!e.training)e.mesh.rotation.y+=da*Math.min(1,dt*5);if(e.training)continue;
 if(e.shotPlan){e.shotPlan.remaining-=dt;e.mesh.userData.flash.visible=true;e.mesh.userData.flash.material.color.setHex(0xffc55e);e.mesh.userData.flash.scale.setScalar(.35+.15*Math.sin(totalTime*25));e.mesh.userData.legs.forEach(l=>l.rotation.x=exp(l.rotation.x,0,12,dt));if(e.shotPlan.remaining<=0){launchBotShot(e.shotPlan,e.id);e.shotPlan=null;e.mesh.userData.flash.material.color.setHex(0xffdf9e);fireAgent(e.mesh);audio?.play('shot',weapons[0]);e.cooldown=rand(1.8,3.4)/(1+Math.min(wave*.04,.5))/(e.multiplier||1)}continue}
 let dx=0,dz=0;if(dist>7){dir.normalize();dx=dir.x*e.speed*dt;dz=dir.z*e.speed*dt}else if(dist<4){dir.normalize();dx=-dir.x*e.speed*dt;dz=-dir.z*e.speed*dt}else{dx=Math.cos(angle)*e.strafe*e.speed*dt*.5;dz=-Math.sin(angle)*e.strafe*e.speed*dt*.5}const pos=e.mesh.position;let moved=false;if(validPosition(pos.x+dx,pos.z,.45)){pos.x+=dx;moved=true}if(validPosition(pos.x,pos.z+dz,.45)){pos.z+=dz;moved=true}if(!moved&&dist>7){e.turn-=dt;const tx=Math.cos(angle)*e.strafe*e.speed*dt,tz=-Math.sin(angle)*e.strafe*e.speed*dt;if(validPosition(pos.x+tx,pos.z+tz,.45)){pos.x+=tx;pos.z+=tz}else if(e.turn<=0){e.strafe*=-1;e.turn=1}}
 e.mesh.userData.legs.forEach((l,i)=>l.rotation.x=Math.sin(e.phase+i*Math.PI)*.37);e.mesh.position.y=Math.abs(Math.sin(e.phase))*.035;e.cooldown-=dt;
 if(e.cooldown<0&&dist<35){const from=pos.clone().add(new THREE.Vector3(0,1.3,0)),to=player.pos.clone().add(new THREE.Vector3(0,rand(1.2,1.9)*player.height/1.7,0));if(lineOfSight(from,to)){e.shotPlan=planBotShot({origin:from.toArray(),target:to.toArray(),velocity:player.vel.toArray(),difficulty:mode==='bots'?practice.difficulty:wave>6?'hard':'normal',wave});e.shotPlan.remaining=e.shotPlan.readyDelay}else e.cooldown=.4}
 }}

let hubReturnMap=0;
function spawnHubStations(){hubRespawns=[];for(const station of hubStations){let e;if(station.target){const model=makeRangeTarget(THREE);model.position.set(station.x,0,station.z);model.rotation.y=Math.PI;worldGroup.add(model);e={id:station.id,mesh:model,hp:100,maxHp:100,speed:0,phase:0,training:true,targetKind:'bullseye',hubStation:station.id}}else{spawnEnemy(true);e=enemies[enemies.length-1];e.hubStation=station.id;e.mesh.position.set(station.x,0,station.z);e.mesh.rotation.y=Math.PI}if(station.target){model.traverse(o=>{if(o.isMesh)o.userData.enemy=e});enemies.push(e)}}}
function updateHub(dt){const zone=hubZone(player.pos),step=hubPadStep(hubPadState,zone,dt);if(step.cancel){const generation=++hubGeneration;net.leave();$('waveLabel').textContent='HIDDEN ATRIUM';notice('듀얼 대기 취소')}if(step.start){const generation=++hubGeneration,size=step.start;$('waveLabel').textContent=`${size} VS ${size} 매칭 중`;notice(`${size} VS ${size} 공개 매칭 중`);services.queueFromHub(size,()=>generation===hubGeneration&&mode==='hub').catch(error=>{if(generation===hubGeneration&&mode==='hub'){hubPadState.started=false;$('waveLabel').textContent='HIDDEN ATRIUM';toast(error.message)}})}if(zone?.type==='exit'){hubSession=false;returnLobby(false);return true}if(hubPadState.id&&!hubPadState.started)$('waveLabel').textContent=`${zone.size} VS ${zone.size} · ${Math.max(0,.65-hubPadState.time).toFixed(1)}초`;if(hubPadState.started&&net.queued)$('waveLabel').textContent=`${zone.size} VS ${zone.size} · ${net.queueCount||'대기 중'}`;for(let i=hubRespawns.length-1;i>=0;i--)if(hubRespawns[i].at<=totalTime){const id=hubRespawns.splice(i,1)[0].station,station=hubStations.find(s=>s.id===id);if(station?.target){const model=makeRangeTarget(THREE);model.position.set(station.x,0,station.z);model.rotation.y=Math.PI;worldGroup.add(model);const e={id:station.id,mesh:model,hp:100,maxHp:100,speed:0,phase:0,training:true,targetKind:'bullseye',hubStation:id};model.traverse(o=>{if(o.isMesh)o.userData.enemy=e});enemies.push(e)}else{spawnEnemy(true);const e=enemies[enemies.length-1];e.hubStation=id;e.mesh.position.set(station.x,0,station.z);e.mesh.rotation.y=Math.PI}}return false}
