function saveSettings(){storage.set('settings',settings);audio?.setLevels(settings.volume,settings.music)}
function resize(){const w=innerWidth,h=innerHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();viewCamera.aspect=Math.max(1.4,w/h);viewCamera.updateProjectionMatrix()}
function lobbyCamera(t=0){const narrow=innerWidth<800;camera.fov=narrow?55:48;camera.position.set(narrow?18:20,7.8,24.5);camera.lookAt(narrow?3:1.5,2.8,-3);camera.position.x+=Math.sin(t*.1)*.3;camera.updateProjectionMatrix();if(lobbyAgent){lobbyAgent.visible=true;lobbyAgent.rotation.y=.55+Math.sin(t*.25)*.04;lobbyAgent.position.y=Math.sin(t*.9)*.014;lobbyAgent.userData.arms.forEach((a,i)=>a.rotation.x=Math.sin(t*.9+i)*.015)}}
function updateEffects(dt){updateDyingAgents(dt);for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.life-=dt;if(e.life<=0){scene.remove(e.mesh);e.mesh.geometry.dispose();e.mesh.material.dispose();effects.splice(i,1)}else{e.mesh.material.opacity=e.life/e.max;if(e.vel){e.vel.y-=12*dt;e.mesh.position.addScaledVector(e.vel,dt)}}}muzzleTime=Math.max(0,muzzleTime-dt);muzzle.visible=muzzleTime>0;muzzleLight.intensity=muzzleTime>0?4:0;for(let i=floatingDamage.length-1;i>=0;i--){const f=floatingDamage[i];f.life-=dt;if(f.life<=0){f.node.remove();floatingDamage.splice(i,1);continue}const point=f.point.clone();point.y+=(1-f.life)*.75;point.project(camera);f.node.style.left=((point.x*.5+.5)*innerWidth)+'px';f.node.style.top=((-point.y*.5+.5)*innerHeight)+'px';f.node.style.opacity=point.z<1?Math.min(1,f.life*3):0}hitTime=Math.max(0,hitTime-dt);$('hitmarker').style.opacity=hitTime>0?1:0;damageOpacity=exp(damageOpacity,0,7,dt);$('damageFlash').style.opacity=damageOpacity;announcementTime=Math.max(0,announcementTime-dt);if(announcementTime===0)$('announcement').style.opacity=0;noticeTime=Math.max(0,noticeTime-dt);if(noticeTime===0)$('pickupNotice').style.opacity=0}
function frame(now){
 requestAnimationFrame(frame);const dt=Math.min((now-lastTime)/1000,.07)||.016;lastTime=now;elapsed+=dt;
 if(combat){
  if(mode==='online')updateRemoteAgents(dt);
  if(!paused){totalTime+=dt;shotCooldown=Math.max(0,shotCooldown-dt);if(reloading>0){reloading-=dt;if(reloading<=0){completeWeaponReload()}}
   if(adminEnabled&&adminCheats.health)player.health=MAX_HEALTH;if(!onlineDead){updatePlayer(dt);if(isTouch)updateAimAssist(dt);if(mouse.down&&weapons[selectedWeapon].auto)shoot();if(isTouch)updateAutoFire(dt);if(mouse.down&&weapons[selectedWeapon].mechanic==='arrow'&&!drawing&&shotCooldown<=0&&reloading<=0)beginAttack()}
   if(mode==='hub'&&updateHub(dt))return;
   if(mode==='online'){networkClock+=dt;if(networkClock>=.05){networkClock=0;sendNetworkPosition()}}else{updateEnemies(dt);for(let i=respawns.length-1;i>=0;i--)if(respawns[i]<=totalTime){respawns.splice(i,1);spawnEnemy(mode==='training')}}
   updateProjectiles(dt);if(mode==='waves'&&!enemies.length)clearBotShots();else if(mode!=='online')updateBotProjectiles(dt);updateEffects(dt);
   if(!paused&&mode==='waves'&&!enemies.length){if(!waveDelay){completeWave()}else{waveDelay-=dt;if(waveDelay<=0){wave++;startWave()}}}
   if(mode==='timed'&&totalTime>=180)finish(true);updateHud();drawMinimap();
  }
  renderer.autoClear=true;renderer.render(scene,camera);renderer.autoClear=false;renderer.clearDepth();weaponRig.visible=showViewWeapon(viewMode==='third',motion.ads,onlineDead);renderer.render(viewScene,viewCamera);renderer.autoClear=true;
 }else{lobbyCamera(elapsed);for(const o of decor)o.rotation.z+=dt*.1;if(lobbyAgent?.userData.easterRing)lobbyAgent.userData.easterRing.material.opacity=.52+Math.sin(elapsed*3)*.22;renderer.render(scene,camera)}
}
async function init(){try{renderer=new THREE.WebGLRenderer({canvas:$('world'),antialias:true,alpha:false,powerPreference:'high-performance',preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,isTouch?1.5:1.75));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;renderer.shadowMap.enabled=settings.shadows;renderer.shadowMap.type=THREE.PCFSoftShadowMap;scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(85,innerWidth/innerHeight,.08,240);viewScene=new THREE.Scene();loadRobotArmor();viewCamera=new THREE.PerspectiveCamera(70,innerWidth/innerHeight,.02,10);viewScene.add(new THREE.HemisphereLight(0xf3ffe9,0x535f45,3));const vl=new THREE.DirectionalLight(0xffedce,2.5);vl.position.set(-3,4,4);viewScene.add(vl);resize();$('loadingText').textContent=maps.length+'개 전장과 '+weapons.length+'종 무기 준비 중';// Generate real 3D thumbnails from each playable arena.
const oldSize=renderer.getSize(new THREE.Vector2()),ratio=renderer.getPixelRatio();renderer.setPixelRatio(1);renderer.setSize(400,240,false);camera.aspect=400/240;for(let i=0;i<maps.length;i++){buildMap(i);lobbyAgent.visible=false;camera.fov=53;camera.position.set(22,13,24);camera.lookAt(0,1,-5);camera.updateProjectionMatrix();renderer.render(scene,camera);thumbs.push(renderer.domElement.toDataURL('image/jpeg',.84))}renderer.setPixelRatio(ratio);buildMap(0);reconcileLoadout();createWeapon();resize();renderMaps();renderRecords();setupEvents();lobbyCamera();renderer.render(scene,camera);$('loading').classList.add('fade');setTimeout(()=>$('loading').hidden=true,700);requestAnimationFrame(frame);window.vectorGame={get state(){return{state,combat,paused,map:selectedMap,weapon:selectedWeapon,weaponCount:weapons.length,viewMode,dash:player.dash||0,dashCooldown:player.dashCooldown||0,mobility:weapons[selectedWeapon].mobility,mouseMode:document.pointerLockElement===$('world')?'locked':pointerLockPending?'requesting':pointerFallback?'edge':'inactive',slots:quickSlots.slice(),coins:services.wallet.coins,mapCount:maps.length,headDamage:damageForHit(weapons[selectedWeapon],true),bodyDamage:weapons[selectedWeapon].damage,kills,score,ammo,reserveAmmo,health:player.health,meleePerk:weapons[quickSlots[2]].perk,meleeReadyAt:player.meleeReadyAt,stunned:isPlayerStunned(),wave,enemies:enemies.length,position:player.pos.toArray(),yaw:player.yaw,pitch:player.pitch,speed:player.speed,grounded:player.grounded,slide:player.slide,time:totalTime}},weapons:weapons.map(({id,name,cat,damage,headMultiplier,rate,mag,reserve,reach,perk,backMultiplier})=>({id,name,cat,damage,headMultiplier,rate,mag,reserve,reach,perk,backMultiplier}))}}catch(error){console.error(error);$('loading').innerHTML='<div class="loading-mark">V</div><b>VECTOR</b><p>3D 화면을 시작할 수 없습니다.</p><span>WebGL을 지원하는 브라우저에서 하드웨어 가속을 켜고 다시 열어주세요.</span><button class="secondary" style="width:200px;margin-top:30px" onclick="location.reload()">다시 시도 ↻</button>'}}
init();

function sendNetworkPosition(){if(mode!=='online'||!combat||!net.connected||onlineDead)return;net.send({type:'move',x:player.pos.x,y:player.pos.y,z:player.pos.z,yaw:player.yaw,pitch:player.pitch,height:player.height})}
function removeRemote(id){const a=remoteAgents.get(id);if(!a)return;worldGroup.remove(a.mesh);a.mesh.traverse(o=>{o.geometry?.dispose();if(o.material?.map){o.material.map.dispose();o.material.dispose()}else if(o.material?.userData.agentOwned)o.material.dispose()});remoteAgents.delete(id)}
function syncRemoteSpawn(m){
 const p=net.players.get(m.id);if(p)Object.assign(p,{x:m.x,y:m.y,z:m.z,yaw:m.yaw,height:1.7,health:MAX_HEALTH,respawnAt:0});
 const a=remoteAgents.get(m.id);if(a)a.wasAlive=false;
}
function updateRemoteAgents(dt){
 for(const[id,a]of remoteAgents){
  const p=net.players.get(id);if(!p){removeRemote(id);continue}
  const alive=p.health>0,respawned=alive&&a.wasAlive===false;a.wasAlive=alive;a.mesh.visible=alive;if(!alive)continue;
  const target=new THREE.Vector3(p.x,p.y,p.z),reset=respawned||a.mesh.position.distanceToSquared(target)>25;
  let moving=Math.hypot(p.x-a.mesh.position.x,p.z-a.mesh.position.z)>.015;
  if(reset){a.mesh.position.copy(target);a.mesh.rotation.y=p.yaw+Math.PI;a.mesh.scale.y=1;a.phase=0;a.mesh.userData.legs.forEach(l=>l.rotation.x=0);moving=false}
  else a.mesh.position.lerp(target,1-Math.exp(-15*dt));
  let angle=p.yaw+Math.PI-a.mesh.rotation.y;while(angle>Math.PI)angle-=Math.PI*2;while(angle<-Math.PI)angle+=Math.PI*2;
  a.mesh.rotation.y+=angle*(1-Math.exp(-14*dt));a.mesh.scale.y=1;a.phase+=dt*11;
  a.mesh.userData.legs.forEach((l,i)=>l.rotation.x=exp(l.rotation.x,moving?Math.sin(a.phase+i*Math.PI)*.4:0,12,dt));const priorPose=a.mesh.userData.poseState||{};a.mesh.userData.poseState={phase:a.phase,moveSpeed:moving?Math.min(9,Math.hypot(p.x-a.mesh.position.x,p.z-a.mesh.position.z)*15):0,crouched:exp(priorPose.crouched||0,p.height<1.4&&p.height>=1?1:0,12,dt),sliding:exp(priorPose.sliding||0,p.height<1?1:0,12,dt),airborne:p.y>.15?1:0,reloadProgress:p.reloadAt>net.serverNow?1-(p.reloadAt-net.serverNow)/1000/(weapons[p.weapon]?.reload||2):0};animateAgent(a.mesh,dt,-(p.pitch||0));
 }
 if(onlineDead&&!paused&&net.match?.phase==='playing'){const p=net.players.get(net.id);if(p){const seconds=Math.max(1,Math.ceil((p.respawnAt-net.serverNow)/1000));announce('RESPAWNING '+seconds,'3초 뒤 전장에 다시 투입됩니다',.2)}}
}
function mergeOnlineRecords(incoming){const merged=new Map();for(const record of [...records,...incoming])merged.set(record.id||[record.date,record.mode,record.score].join('_'),record);records=[...merged.values()].sort((a,b)=>a.date-b.date).slice(-200);storage.set(services.account?'records:'+services.account.username:'records',records);renderRecords()}
function updateTeamHud(){
 const m=net.match;if(!m)return;const own=net.players.get(net.id);if(own)myTeam=own.team;
 const names=['BLUE','ORANGE'];$('hudMode').textContent=`${m.teamSize} VS ${m.teamSize} · ${names[myTeam??0]} TEAM`;$('hudMode').style.color=myTeam===1?'#ffb581':'#b5e0ff';
 $('onlineTeamHud').textContent=names[myTeam??0]+' TEAM';$('onlineTeamHud').style.color=myTeam===1?'#ffb581':'#b5e0ff';
 const count=[...net.players.values()].filter(p=>p.connected).length;let key=m.phase;
 if(m.phase==='waiting'){$('waveLabel').textContent=`WAITING ${count} / ${m.capacity}`;$('enemyLabel').textContent='인원이 모이면 평균 레벨을 맞춰 자동 시작';key+='_'+count;if(key!==matchNoticeKey)announce('WAITING FOR PLAYERS',`${count} / ${m.capacity}명 · 방 코드 ${net.room}로 참가할 수 있습니다`,3)}
 else if(m.phase==='countdown'){const seconds=Math.max(1,Math.ceil((m.startsAt-net.serverNow)/1000));$('waveLabel').textContent='START IN '+seconds;$('enemyLabel').textContent=`평균 Lv. ${m.averages[0].toFixed(1)} vs ${m.averages[1].toFixed(1)}`;key+='_'+seconds;if(key!==matchNoticeKey)announce(String(seconds),`${names[myTeam??0]} TEAM · ${m.teamSize}대${m.teamSize}`,1.1)}
 else{$('waveLabel').innerHTML=`<span class="blue-score">${String(m.scores[0]).padStart(2,'0')}</span><small> : </small><span class="orange-score">${String(m.scores[1]).padStart(2,'0')}</span>`;$('enemyLabel').textContent=`목표 ${m.scoreLimit}점 · 평균 Lv. ${m.averages[0].toFixed(1)} vs ${m.averages[1].toFixed(1)}`;$('timerLabel').textContent=formatTime(Math.max(0,(m.endsAt-net.serverNow)/1000));if(m.phase==='playing'&&key!==matchNoticeKey)announce('TEAM DEATHMATCH',`${names[myTeam??0]} TEAM · 아군 피해 없음`,2)}
 matchNoticeKey=key;
}
function handleOnlineResult(message){
 if(!combat||mode!=='online'||onlineResultHandled)return;onlineResultHandled=true;paused=true;state='result';syncMouseMode();keys.clear();mouse.down=false;resetMouseLook(mouse);aim=false;if(document.pointerLockElement)document.exitPointerLock();$('pauseOverlay').hidden=true;$('onlineScoreboard').hidden=true;$('resultOverlay').hidden=false;
 const reward=message.self,match=message.match,outcome=reward?.outcome||(match.winner===null?'draw':match.winner===myTeam?'win':'loss');
 $('resultTitle').textContent={win:'팀의 승리.',loss:'다음 승리를 향해.',draw:'팽팽했던 전투.'}[outcome];$('resultMessage').textContent=`${match.teamSize}대${match.teamSize} · ${match.scores[0]} : ${match.scores[1]}${match.reason==='forfeit'?' · 연결 종료로 경기 종료':''}`;
 $('resultStats').classList.add('match-result-stats');$('resultStats').innerHTML=[['처치 / 어시스트',`${kills} / ${net.players.get(net.id)?.assists||0}`],['획득 XP','+'+(reward?.xp||0)],['전투 레벨',reward?`${reward.levelBefore} → ${reward.levelAfter}`:String(services.profile.level)]].map(([name,value])=>`<span>${name}<b>${value}</b></span>`).join('');
 $('resultProgress').hidden=false;const delta=reward?.ratingDelta||0;$('resultProgress').textContent=`코인 +${reward?.coins||0} C · 실력 점수 ${services.profile.rating} (${delta>=0?'+':''}${delta}) · 승리·처치·팀 기여도 반영${message.saved===false?' · 서버 저장 상태를 확인하세요.':''}`;
 $('retryBtn').innerHTML=(match.kind==='public'?'같은 모드 다시 매칭':'새 코드 방 만들기')+' <span>→</span>';if(reward?.record)mergeOnlineRecords([reward.record]);
}
function setupNetwork(){
 services.init({onEconomy:applyEconomy,getMap:()=>selectedMap,getWeapon:()=>selectedWeapon,toast,initAudio,onPractice:()=>{showTab('play');$('modeSelect').value='bots';$('botOptions').hidden=false;toast('봇 수와 난이도를 고른 뒤 전투 시작을 누르세요.')},onOnline:welcome=>{onlineWelcome=welcome;startGame('online')},onAccount:account=>{adminEnabled=account?.role==='admin';$('adminCheats').hidden=!adminEnabled;$('adminOpen').hidden=!adminEnabled;if(!adminEnabled)adminCheats={speed:false,fly:false,aim:false,evasion:false,health:false,ammo:false};records=account?storage.get('records:'+account.username,[]):storage.get('records',[]);if(account?.records)mergeOnlineRecords(account.records);else renderRecords()},onGuestRecords:incoming=>{if(!services.account)mergeOnlineRecords(incoming)}});
 net.addEventListener('projectile',({detail:m})=>{if(combat&&mode==='online'){makeProjectileVisual(m.projectile);if(m.projectile.kind==='rocket')fireAgent(remoteAgents.get(m.projectile.owner)?.mesh)}});
 net.addEventListener('projectileEnd',({detail:m})=>removeProjectileVisual(m.id));
 net.addEventListener('explosion',({detail:m})=>{if(combat&&mode==='online')explosionVisual(m.position,m.radius)});
 net.addEventListener('impulse',({detail:m})=>{if(combat&&mode==='online'&&m.id===net.id&&!onlineDead){applyImpulse(m.velocity)}});
 net.addEventListener('stun',({detail:m})=>{if(!combat||mode!=='online')return;const p=net.players.get(m.id);if(p)p.stunUntil=m.until;if(m.id===net.id){player.pos.set(m.x,m.y,m.z);player.vel.set(0,0,0);mouse.down=false;cancelDraw();notice('기절 · 잠시 이동·공격 불가')}});
 net.addEventListener('meleeAbility',({detail:m})=>applyOnlineMeleeAbility(m));
 net.addEventListener('meleePerk',({detail:m})=>{if(!combat||mode!=='online'||m.id!==net.id)return;player.health=m.health;player.meleeReadyAt=m.readyAt;for(const row of m.inventory||[]){if(!weapons[row.weapon])continue;magazineInventory.set(row.weapon,row.ammo);reserveInventory.set(row.weapon,row.reserve);if(row.weapon===selectedWeapon){ammo=row.ammo;reserveAmmo=row.reserve}}notice(m.title+' 발동');updateWeaponHud();updateMeleeHud()});
 net.addEventListener('dashAck',({detail:m})=>handleDashAck(m));
 net.addEventListener('equipAck',({detail:m})=>handleEquipAck(m));
 net.addEventListener('reloadAck',({detail:m})=>handleReloadAck(m));
 net.addEventListener('snapshot',({detail:message})=>{
  if(!combat||mode!=='online')return;const live=new Set((message.projectiles||[]).map(p=>p.id));for(const id of projectileVisuals.keys())if(!live.has(id))removeProjectileVisual(id);for(const p of message.projectiles||[]){makeProjectileVisual(p);const v=projectileVisuals.get(p.id);v.position=p.position.slice();v.velocity=p.velocity.slice()}const self=message.players.find(p=>p.id===net.id);
  if(self){if(!pendingDash)player.dashCooldown=Math.max(0,((self.dashReadyAt||0)-message.time)/1000);if(self.stunUntil>message.time)player.dash=0;player.meleeReadyAt=self.meleeReadyAt||0;myTeam=self.team;if(self.health<player.health&&self.health>0){damageOpacity=.7;sound('hurt')}player.health=self.health;kills=self.kills;score=self.kills*100+self.assists*30;onlineDead=self.health<=0;if(onlineDead){keys.clear();mouse.down=false;aim=false;cancelDraw()}syncInventoryFromSnapshot(self,message.time)}
  for(const p of message.players){if(p.id===net.id)continue;const old=remoteAgents.get(p.id);if(old&&old.team!==p.team)removeRemote(p.id);if(!remoteAgents.has(p.id)){const friendly=p.team===myTeam;const mesh=makeAgent(friendly?0x8ca9a7:0xc0a17e,!friendly);mesh.position.set(p.x,p.y,p.z);mesh.rotation.y=p.yaw+Math.PI;mesh.traverse(o=>{if(o.isMesh)o.userData.remote=p.id});const lm=label(`${p.bot?'AI · ':''}${p.name} · Lv.${p.level}`,512,80,friendly?'#ccf5df':'#ffd1a5','#122017b0',38);const tag=new THREE.Sprite(new THREE.SpriteMaterial({map:lm.map,transparent:true,depthTest:false}));lm.dispose();tag.position.set(0,2.5,0);tag.scale.set(2,.3,1);tag.raycast=()=>{};mesh.add(tag);worldGroup.add(mesh);remoteAgents.set(p.id,{mesh,phase:Math.random()*6,team:p.team,wasAlive:p.health>0})}}
  for(const id of remoteAgents.keys())if(!net.players.has(id))removeRemote(id);updateHud();drawMinimap();
 });
 net.addEventListener('matchStart',()=>{if(combat&&mode==='online'){totalTime=0;shotCooldown=.3;matchNoticeKey=''}});
 net.addEventListener('matchEnd',({detail:message})=>handleOnlineResult(message));
 net.addEventListener('shot',({detail:m})=>{if(!combat||mode!=='online')return;if(m.mechanic==='melee')return;fireAgent(remoteAgents.get(m.id)?.mesh);for(const ray of m.rays)addLine(new THREE.Vector3(...m.origin),new THREE.Vector3(...ray),0xffa76e,.1)});
 net.addEventListener('hit',({detail:m})=>{if(!combat||mode!=='online')return;flashAgent(remoteAgents.get(m.target)?.mesh);if(m.target===net.id){damageOpacity=.85;sound('hurt')}if(m.shooter!==net.id||m.target===net.id)return;const p=net.players.get(m.target);const point=p?new THREE.Vector3(p.x,p.y+(m.head?2:1.4)*(p.height/1.7),p.z):camera.position.clone().add(new THREE.Vector3(0,0,-5).applyQuaternion(camera.quaternion));if(m.rear)meleeBackSwing=true;hitFeedback(m.damage,m.head,m.killed,point,m.distance,m.health,m.execution?'BACKSTAB':m.rear?'REAR HIT':null);if(m.killed)notice(m.head?'HEADSHOT +100':'ELIMINATION +100')});
 net.addEventListener('elimination',({detail:m})=>{if(!combat||mode!=='online')return;const row=document.createElement('div');const b=document.createElement('b');b.textContent=m.shooterName;row.append(b,document.createTextNode(' → '+m.targetName+(m.head?' · HEADSHOT':'')));$('killFeed').prepend(row);setTimeout(()=>row.remove(),3100)});
 net.addEventListener('spawn',({detail:m})=>{if(!combat||mode!=='online')return;if(m.id!==net.id){syncRemoteSpawn(m);return}player.pos.set(m.x,m.y,m.z);player.vel.set(0,0,0);player.yaw=m.yaw;player.pitch=0;player.health=MAX_HEALTH;player.height=1.7;player.jumps=0;player.grounded=true;player.slide=0;magazineInventory.clear();reserveInventory.clear();rigWeapon=null;resetMotion();onlineDead=false;pendingEquip=0;pendingReload=0;pendingOnlineShots=[];if(Number.isInteger(m.weapon)&&weapons[m.weapon]&&m.weapon!==selectedWeapon){selectedWeapon=m.weapon;inspectedWeapon=m.weapon;createWeapon(false)}ammo=m.ammo??weapons[selectedWeapon].mag;reserveAmmo=m.reserve??weapons[selectedWeapon].reserve;reserveInventory.set(selectedWeapon,reserveAmmo);rigWeapon=selectedWeapon;reloading=0;magazineInventory.set(selectedWeapon,ammo);updateWeaponHud();if(net.match?.phase==='playing')announce('BACK IN ACTION','2초 동안 부활 보호를 받습니다',2)});
 net.addEventListener('correct',({detail:m})=>{if(combat&&mode==='online'&&!onlineDead){player.pos.set(m.x,m.y,m.z);player.vel.x=0;player.vel.z=0}});
 net.addEventListener('shotAck',({detail:m})=>handleShotAck(m));
 net.addEventListener('disconnect',()=>{if(combat&&mode==='online'&&state!=='result'){returnLobby();toast('온라인 서버와 연결이 끊어졌습니다. 다시 참가해 주세요.')}});
}
